// antd v6 tokens + the theme (light / dark) controller — GENERATED by scaffold_os.py (the colour and size values). One control height and one
// radius for every field, so inputs, selects, pickers and search line up. antd derives hover/active shades from these, so it gets the
// same hex values that tokens.css declares as variables; `primary` is the brand, or ink when the brand is a red (primary_mode).
//
// v4.9 dark mode: `html[data-theme="dark"|"light"]` is the single switch (inline script in app/layout.tsx before first paint; <ThemeProvider> in
// Providers.jsx persists `pucho-theme` and mirrors it to a cookie). This file is PURE (no React, no antd) so the server layout can use it too:
//   DARK            antd token + component overrides for the dark theme (Providers adds antd's darkAlgorithm) — the same values as tokens.css
//   darkStyleText() the dark values that need arithmetic (the lifted primary, the brand-hued pastel neutrals, the chart colour) as plain
//                   hex in one <style> in <head> — hex (not oklch()) so every browser and every contrast probe reads them as rgb().

export const CONTROL_HEIGHT = 44;
export const THEME = {
  token: {
    colorPrimary: '#141413', controlHeight: CONTROL_HEIGHT, borderRadius: 12, borderRadiusLG: 16, borderRadiusSM: 8,
    fontFamily: 'var(--font-sans)',
    colorText: '#141413', colorTextSecondary: '#45413A', colorTextTertiary: '#676F77', colorTextQuaternary: '#676F77', colorTextPlaceholder: '#676F77', colorTextDisabled: '#B5AFA4',
    colorBorder: 'rgba(30, 30, 29, 0.30)', colorBorderSecondary: 'rgba(31, 30, 29, 0.15)', colorBgContainer: '#FFFFFF', colorBgLayout: '#FFFFFF',
    colorSuccess: '#4C8C6A', colorWarning: '#B4763B', colorError: '#B45B4E', colorInfo: '#7B5CFF',
    // Depth is a hairline; shadow only on what floats.
    boxShadow: '0 2px 6px rgba(21,24,28,0.06)', boxShadowSecondary: '0 14px 40px rgba(20, 20, 19, 0.10)',
  },
  components: {
    Button: { primaryShadow: 'none', defaultShadow: 'none', dangerShadow: 'none', fontWeight: 500, colorPrimaryHover: '#2A2620', colorPrimaryActive: '#2A2620' },
    // v4.8 (DS): a toggle, a tick and a radio turn on in the accent (violet), never in the primary ink; a checkbox is 20px with r8
    Switch: { colorPrimary: '#7B5CFF', colorPrimaryHover: '#7B5CFF' },
    Checkbox: { colorPrimary: '#7B5CFF', colorPrimaryHover: '#7B5CFF', borderRadiusSM: 8 },
    Radio: { colorPrimary: '#7B5CFF', colorPrimaryHover: '#7B5CFF' },
    Select: { optionHeight: 36 },
    Segmented: { itemSelectedColor: '#141413', itemHoverColor: '#141413', trackBg: '#F5F4F0' },
    Steps: { iconSize: 28 },
    Tag: { borderRadiusSM: 8 },
  },
};

// ── dark ────────────────────────────────────────────────────────────────────────────────────────────────────
const TONE = 'pucho';
const BRAND_HEX = '#0B8F6A';
const PRIMARY_HEX = '#141413';

// sRGB hex <-> OKLCH (Björn Ottosson's matrices) — the pastel dark neutrals are derived from the brand hue exactly the way
// tokens.css derives them (oklch(from var(--brand-seed) L C h)), so antd's hex and the CSS variables are the same colour.
const lin = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const gam = (c) => (c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055);
function hexToOklch(hex) {
  const n = parseInt(hex.replace('#', '').slice(0, 6), 16); const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => lin(v / 255));
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b), m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b), s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, A = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, B = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return { l: L, c: Math.hypot(A, B), h: (Math.atan2(B, A) * 180) / Math.PI };
}
function oklchToHex(L, C, hDeg) {
  const a = C * Math.cos((hDeg * Math.PI) / 180), b = C * Math.sin((hDeg * Math.PI) / 180);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3, m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3, s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const rgb = [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s];
  return '#' + rgb.map((v) => Math.round(Math.min(1, Math.max(0, gam(v))) * 255).toString(16).padStart(2, '0')).join('');
}
const brandHue = hexToOklch(BRAND_HEX).h;
const pastel = (L, C) => oklchToHex(L, C, brandHue);

const DARK_TONES = {
  pucho: {
    bg: '#141413', surface: '#1d1d1c', surface2: '#272522', ink: '#f7f6f3', ink2: '#dedad2', ink3: '#b7b1a6', ink4: '#8d897f',
    line: 'rgba(255,255,255,0.12)', lineStrong: 'rgba(255,255,255,0.26)', accent: '#8b72ff', ok: '#4c8c6a', warn: '#c98a3f', bad: '#c4695b', info: '#8b72ff',
  },
  graphite: {
    bg: '#0f1114', surface: '#171a1f', surface2: '#1f2329', ink: '#f2f4f7', ink2: '#cdd3da', ink3: '#a0a9b4', ink4: '#78818c',
    line: 'rgba(255,255,255,0.11)', lineStrong: 'rgba(255,255,255,0.26)', accent: '#6aa5f2', ok: '#2e9e5e', warn: '#c98516', bad: '#d9534a', info: '#4f8fe0',
  },
  pastel: {
    bg: pastel(0.175, 0.028), surface: pastel(0.215, 0.03), surface2: pastel(0.255, 0.032), ink: pastel(0.965, 0.01), ink2: pastel(0.87, 0.018), ink3: pastel(0.77, 0.03), ink4: pastel(0.62, 0.035),
    line: 'rgba(255,255,255,0.12)', lineStrong: 'rgba(255,255,255,0.26)', accent: pastel(0.74, 0.12), ok: '#2eb872', warn: '#f5a524', bad: '#f0544f', info: '#4f86f7',
  },
};
const D = DARK_TONES[TONE] ?? DARK_TONES.pucho;

// The dark primary mirrors the CSS rule in tokens.css: ink -> near-white (label dark); a chromatic brand -> lightness clamped to .50–.58 (label white).
const seed = hexToOklch(PRIMARY_HEX); const k = Math.min(1, Math.max(0, seed.c * 25));
const PRIMARY_L = 0.965 * (1 - k) + Math.min(0.58, Math.max(0.5, seed.l)) * k;
const PRIMARY_DARK = oklchToHex(PRIMARY_L, seed.c, seed.h);
const PRIMARY_DARK_HOVER = oklchToHex(PRIMARY_L - 0.05, seed.c, seed.h);
const ON_PRIMARY_DARK = k > 0.5 ? '#ffffff' : '#141413';

export const DARK = {
  token: {
    ...THEME.token,
    colorPrimary: PRIMARY_DARK, colorTextLightSolid: ON_PRIMARY_DARK,
    colorText: D.ink, colorTextSecondary: D.ink2, colorTextTertiary: D.ink3, colorTextQuaternary: D.ink3, colorTextPlaceholder: D.ink3, colorTextDisabled: D.ink4,
    colorBorder: D.lineStrong, colorBorderSecondary: D.line, colorSplit: D.line,
    colorBgContainer: D.surface, colorBgElevated: D.surface, colorBgLayout: D.bg, colorBgSpotlight: D.surface2,
    colorFillAlter: D.surface2, colorFillContent: D.surface2, colorFillSecondary: 'rgba(255,255,255,0.08)', colorFillTertiary: 'rgba(255,255,255,0.06)', colorFillQuaternary: 'rgba(255,255,255,0.04)',
    colorSuccess: D.ok, colorWarning: D.warn, colorError: D.bad, colorInfo: D.info,
    boxShadow: '0 2px 6px rgba(0,0,0,0.35)', boxShadowSecondary: '0 14px 40px rgba(0,0,0,0.55)',
  },
  components: {
    ...THEME.components,
    Button: { ...THEME.components.Button, colorPrimaryHover: PRIMARY_DARK_HOVER, colorPrimaryActive: PRIMARY_DARK_HOVER, primaryColor: ON_PRIMARY_DARK, defaultBg: D.surface, defaultBorderColor: D.lineStrong, defaultColor: D.ink },
    Switch: { colorPrimary: D.accent, colorPrimaryHover: D.accent },
    Checkbox: { ...THEME.components.Checkbox, colorPrimary: D.accent, colorPrimaryHover: D.accent },
    Radio: { colorPrimary: D.accent, colorPrimaryHover: D.accent },
    Segmented: { ...THEME.components.Segmented, itemSelectedColor: D.ink, itemSelectedBg: D.surface, itemHoverColor: D.ink, itemColor: D.ink3, trackBg: D.surface2 },
    Table: { headerBg: D.surface2, headerColor: D.ink3, rowHoverBg: 'rgba(255,255,255,0.04)', borderColor: D.line, colorBgContainer: D.surface },
    Modal: { contentBg: D.surface, headerBg: D.surface, footerBg: D.surface },
    Drawer: { colorBgElevated: D.surface },
    Select: { ...THEME.components.Select, optionSelectedBg: D.surface2, optionActiveBg: 'rgba(255,255,255,0.06)', optionSelectedColor: D.ink },
    Tabs: { itemColor: D.ink3, itemHoverColor: D.ink, itemSelectedColor: D.ink, inkBarColor: D.ink },
  },
};

// ── the dark values that need arithmetic, as plain hex ─────────────────────────────────────────────────────────────
const CHART_HEX = '#0B8F6A';
const hex = (h) => h; const rgbOf = (h) => { const n = parseInt(h.replace('#', ''), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const alpha = (h, a) => `rgb(${rgbOf(h).join(' ')} / ${a})`;
const brandInk = oklchToHex(0.86, Math.min(hexToOklch(BRAND_HEX).c, 0.12), brandHue);
const brandText = oklchToHex(0.8, Math.min(hexToOklch(BRAND_HEX).c, 0.14), brandHue);
const primaryText = oklchToHex(0.965 * (1 - k) + 0.8 * k, seed.c, seed.h);
const chartSeed = hexToOklch(CHART_HEX);
const chartDark = oklchToHex(Math.min(0.82, Math.max(0.68, chartSeed.l)), chartSeed.c, chartSeed.h);

/** CSS for <head>: `html[data-theme='dark'][data-tone][data-theme-mode]` (specificity 0,4,1 — above every static dark block in tokens.css). */
export function darkStyleText() {
  const v = {
    '--primary': hex(PRIMARY_DARK), '--on-primary': ON_PRIMARY_DARK, '--primary-text': hex(primaryText),
    '--brand-ink': hex(brandInk), '--brand-text': hex(brandText),
  };
  if (TONE !== 'graphite') v['--chart-one'] = hex(chartDark);
  if (TONE === 'pastel') Object.assign(v, {
    '--bg': D.bg, '--surface': D.surface, '--surface-2': D.surface2, '--ink': D.ink, '--ink-2': D.ink2, '--ink-3': D.ink3, '--ink-4': D.ink4,
    '--accent': D.accent, '--accent-soft': alpha(D.accent, 0.2), '--ink-hover': D.ink2, '--nav-bg': pastel(0.195, 0.03),
  });
  return `html[data-theme='dark'][data-tone][data-theme-mode]{${Object.entries(v).map(([k2, x]) => `${k2}:${x}`).join(';')}}`;
}
